[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $templateAction = $null
    $optionArguments = @($CliArguments)
    if ($Command.Equals('template', [StringComparison]::OrdinalIgnoreCase)) {
        if ($optionArguments.Count -eq 0) {
            throw 'Missing template action: save, list, or remove.'
        }
        $templateAction = $optionArguments[0].ToLowerInvariant()
        $optionArguments = @($optionArguments | Select-Object -Skip 1)
    }

    $options = ConvertFrom-TaskForgeArguments -Arguments $optionArguments
    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    else {
        $defaultDataFile
    }
    $asJson = $options.Contains('json')
    $templateFile = Get-TemplateStorePath -DataFile $dataFile
    $templateBanner = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/template.txt'

    switch ($Command.ToLowerInvariant()) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'template', 'data-file', 'json')
            $template = $null
            if ($options.Contains('template')) {
                $templateName = Get-ValidTemplateName -Name (Get-RequiredOption -Options $options -Name 'template')
                $template = Find-Template -Templates @(Read-TemplateStore -Path $templateFile) -Name $templateName
                if ($null -eq $template) {
                    throw "Template '$templateName' was not found."
                }
            }

            if ($options.Contains('title')) {
                $title = (Get-RequiredOption -Options $options -Name 'title').Trim()
            }
            elseif ($null -ne $template) {
                $title = [string]$template.title
            }
            else {
                throw 'Missing required option: --title'
            }

            $description = if ($options.Contains('description')) {
                Get-OptionValue -Options $options -Name 'description'
            }
            elseif ($null -ne $template -and $null -ne $template.PSObject.Properties['description']) {
                [string]$template.description
            }
            else {
                ''
            }

            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title
                description = $description
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'template' {
            switch ($templateAction) {
                'save' {
                    Assert-KnownOptions -Options $options -Allowed @('name', 'title', 'description', 'data-file', 'json')
                    $name = Get-ValidTemplateName -Name (Get-RequiredOption -Options $options -Name 'name')
                    $title = (Get-RequiredOption -Options $options -Name 'title').Trim()
                    $description = if ($options.Contains('description')) {
                        Get-OptionValue -Options $options -Name 'description'
                    }
                    else {
                        ''
                    }
                    $templates = @(Read-TemplateStore -Path $templateFile)
                    if ($null -ne (Find-Template -Templates $templates -Name $name)) {
                        throw "Template '$name' already exists."
                    }
                    $template = [pscustomobject][ordered]@{
                        name = $name
                        title = $title
                        description = $description
                    }
                    Write-TemplateStore -Path $templateFile -Templates @($templates + $template)
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $template -AsJson $true
                    }
                    else {
                        Write-TemplateBanner -Path $templateBanner
                        "Saved template '$name'."
                    }
                }
                'list' {
                    Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
                    $templates = @(Read-TemplateStore -Path $templateFile |
                        Sort-Object @{ Expression = { ([string]$_.name).ToUpperInvariant() } }, @{ Expression = { [string]$_.name } })
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $templates -AsJson $true
                    }
                    else {
                        Write-TemplateBanner -Path $templateBanner
                        if ($templates.Count -eq 0) {
                            'No templates.'
                        }
                        else {
                            $templates | ForEach-Object { "$($_.name): $($_.title)" }
                        }
                    }
                }
                'remove' {
                    Assert-KnownOptions -Options $options -Allowed @('name', 'data-file', 'json')
                    $name = Get-ValidTemplateName -Name (Get-RequiredOption -Options $options -Name 'name')
                    $templates = @(Read-TemplateStore -Path $templateFile)
                    $template = Find-Template -Templates $templates -Name $name
                    if ($null -eq $template) {
                        throw "Template '$name' was not found."
                    }
                    $remaining = @($templates | Where-Object {
                        -not [string]::Equals([string]$_.name, $name, [StringComparison]::OrdinalIgnoreCase)
                    })
                    Write-TemplateStore -Path $templateFile -Templates $remaining
                    $summary = [pscustomobject]@{ removedName = [string]$template.name }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value $summary -AsJson $true
                    }
                    else {
                        Write-TemplateBanner -Path $templateBanner
                        "Removed template '$($template.name)'."
                    }
                }
                default {
                    throw "Unknown template action: $templateAction"
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @()
            @'
TaskForge
  add (--title TEXT | --template NAME) [--description TEXT] [--data-file PATH] [--json]
  list [--data-file PATH] [--json]
  complete --id ID [--data-file PATH] [--json]
  remove --id ID [--data-file PATH] [--json]
  template save --name NAME --title TEXT [--description TEXT] [--data-file PATH] [--json]
  template list [--data-file PATH] [--json]
  template remove --name NAME [--data-file PATH] [--json]
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
